from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if (r,c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            if len(cells)>=6:
                height=max(x for x,y in cells)-min(x for x,y in cells)+1
                width=max(y for x,y in cells)-min(y for x,y in cells)+1
                if len(cells)/(height*width)>=0.6:
                    objects.append((len(cells),color))
    color=max(objects)[1]
    return [[color]*3 for _ in range(3)]
